import pandas as pd
from collections import Counter

def task_func(d):
    keys = ("x", "y", "z")
    counts = {key: Counter() for key in keys}

    if not d:
        return counts

    for item in d:
        if not isinstance(item, dict):
            continue

        for key in keys:
            if key in item:
                counts[key][item[key]] += 1

    return counts
